using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Animations;
using UnityEngine.Playables;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UTS.Characters;
using Praktikum5.FSM;

[InitializeOnLoad]
public static class PlayerLocomotionDiagnostics
{
    static string Folder=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"Library/ZU_Locomotion");
    static string last=SessionState.GetString("ZU.Locomotion.Command","");
    [Serializable] class Cmd{public string op,nonce;}
    static PlayerLocomotionDiagnostics(){EditorApplication.update+=Tick;EditorApplication.update+=RuntimeTick;EditorApplication.playModeStateChanged+=Mode;}
    static void Tick(){string f=Path.Combine(Folder,"command.json");if(!File.Exists(f)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;string t=File.ReadAllText(f);if(t==last)return;last=t;SessionState.SetString("ZU.Locomotion.Command",t);try{var c=JsonUtility.FromJson<Cmd>(t);if(c.op=="audit")Audit();else if(c.op=="fix")Fix();else if(c.op=="fix-crouch")FixCrouch();else if(c.op=="natural-crouch")NaturalCrouch();else if(c.op=="test-crouch-native"){SessionState.SetBool("ZU.Crouch.DisableAlignment",true);CharacterUpgradePlayQA.Begin();}else if(c.op=="mesh")MeshAudit();else if(c.op=="runtime")BeginRuntime();else if(c.op=="runtime-ik"){SessionState.SetBool("ZU.LegIK",true);BeginRuntime();}else if(c.op=="refresh")AssetDatabase.Refresh();}catch(Exception e){File.WriteAllText(Path.Combine(Folder,"error.txt"),e.ToString());Debug.LogException(e);}}
    [Serializable] class Pose{public float time,leftKnee,rightKnee,leftFootY,rightFootY,hipsY;public Vector3 leftKneePosition,rightKneePosition,leftFootPosition,rightFootPosition;}
    [Serializable] class Cycle{public string model,clip;public bool footIK;public float duration,humanScale;public Pose[] frames;}
    [Serializable] class Report{public string scene;public bool standingFootIK;public string[] components;public Cycle[] cycles;}
    static Pose Measure(Animator a,float time){var hip=a.GetBoneTransform(HumanBodyBones.Hips);var lu=a.GetBoneTransform(HumanBodyBones.LeftUpperLeg);var ll=a.GetBoneTransform(HumanBodyBones.LeftLowerLeg);var lf=a.GetBoneTransform(HumanBodyBones.LeftFoot);var ru=a.GetBoneTransform(HumanBodyBones.RightUpperLeg);var rl=a.GetBoneTransform(HumanBodyBones.RightLowerLeg);var rf=a.GetBoneTransform(HumanBodyBones.RightFoot);return new Pose{time=time,leftKnee=Vector3.Angle(lu.position-ll.position,lf.position-ll.position),rightKnee=Vector3.Angle(ru.position-rl.position,rf.position-rl.position),leftFootY=lf.position.y,rightFootY=rf.position.y,hipsY=hip.position.y,leftKneePosition=ll.position,rightKneePosition=rl.position,leftFootPosition=lf.position,rightFootPosition=rf.position};}
    static AnimationClip Clip(string name)=>AssetDatabase.LoadAllAssetsAtPath("Assets/CharacterUpgrade/Animations/Player/"+name+".fbx").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview"));
    static Texture2D Frame(Camera camera,int w,int h){var rt=new RenderTexture(w,h,24);camera.targetTexture=rt;camera.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(w,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,w,h),0,0);tex.Apply();RenderTexture.active=prev;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);return tex;}
    static void Audit(){
        if(Application.isPlaying)throw new Exception("Audit in Edit mode");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var live=player.GetComponent<HumanoidAnimationDriver>().Animator;var ctrl=live.runtimeAnimatorController as AnimatorController;var state=ctrl.layers[0].stateMachine.states.Single(s=>s.state.name=="Standing").state;
        var report=new Report{scene=SceneManager.GetActiveScene().path,standingFootIK=state.iKOnFeet,components=player.GetComponentsInChildren<MonoBehaviour>(true).Where(x=>x).Select(x=>x.GetType().FullName).ToArray()};var cycles=new List<Cycle>();
        var scene=EditorSceneManager.NewPreviewScene();var camGo=new GameObject("Leg diagnostic camera");SceneManager.MoveGameObjectToScene(camGo,scene);var camera=camGo.AddComponent<Camera>();camera.scene=scene;camera.orthographic=true;camera.orthographicSize=1.06f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.27f,.3f,.34f);camera.nearClipPlane=.01f;camera.farClipPlane=20;camera.transform.position=new Vector3(3,1.05f,3);camera.transform.LookAt(new Vector3(0,.92f,0));
        var lightGo=new GameObject("Leg diagnostic key");SceneManager.MoveGameObjectToScene(lightGo,scene);var light=lightGo.AddComponent<Light>();light.type=LightType.Directional;light.intensity=2;light.transform.rotation=Quaternion.Euler(35,-35,0);
        try{
            foreach(var clipName in new[]{"Walking2","Running","Idle"}){
                var clip=Clip(clipName);var sheet=new Texture2D(8*280,3*400,TextureFormat.RGB24,false);
                for(int mode=0;mode<3;mode++){
                    var go=UnityEngine.Object.Instantiate(live.gameObject);SceneManager.MoveGameObjectToScene(go,scene);go.name="Diagnostic player";go.transform.SetPositionAndRotation(new Vector3(0,1+live.transform.localPosition.y,0),Quaternion.identity);foreach(var b in go.GetComponentsInChildren<MonoBehaviour>())b.enabled=false;
                    var a=go.GetComponent<Animator>();a.runtimeAnimatorController=null;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.applyRootMotion=false;a.Rebind();
                    var graph=PlayableGraph.Create("Leg diagnostic");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var motion=AnimationClipPlayable.Create(graph,clip);motion.SetApplyFootIK(mode==2);var output=AnimationPlayableOutput.Create(graph,"Pose",a);output.SetSourcePlayable(motion);graph.Play();var poses=new List<Pose>();
                    try{for(int i=0;i<8;i++){float time=clip.length*i/8;motion.SetTime(time);graph.Evaluate(0);poses.Add(Measure(a,time));var cpu=new List<GameObject>();if(mode==1){foreach(var r in go.GetComponentsInChildren<SkinnedMeshRenderer>()){var child=new GameObject("Baked "+r.name);child.transform.SetParent(r.transform,false);var mesh=new Mesh();r.BakeMesh(mesh);child.AddComponent<MeshFilter>().sharedMesh=mesh;child.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;r.enabled=false;cpu.Add(child);}}var tex=Frame(camera,280,400);foreach(var child in cpu){UnityEngine.Object.DestroyImmediate(child.GetComponent<MeshFilter>().sharedMesh);UnityEngine.Object.DestroyImmediate(child);}foreach(var r in go.GetComponentsInChildren<SkinnedMeshRenderer>())r.enabled=true;sheet.SetPixels(i*280,(2-mode)*400,280,400,tex.GetPixels());UnityEngine.Object.DestroyImmediate(tex);}}finally{graph.Destroy();UnityEngine.Object.DestroyImmediate(go);}
                    cycles.Add(new Cycle{model="PlayerChar",clip=clipName,footIK=mode==2,duration=clip.length,humanScale=a?a.humanScale:0,frames=poses.ToArray()});
                }
                sheet.Apply();File.WriteAllBytes(Path.Combine(Folder,clipName+"-meshcheck.png"),sheet.EncodeToPNG());UnityEngine.Object.DestroyImmediate(sheet);
            }
            report.cycles=cycles.ToArray();File.WriteAllText(Path.Combine(Folder,"audit.json"),JsonUtility.ToJson(report,true));
        }finally{EditorSceneManager.ClosePreviewScene(scene);}
    }
    static void MeshAudit(){
        var a=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>().GetComponent<HumanoidAnimationDriver>().Animator;var lines=new List<string>();lines.Add("Quality="+QualitySettings.GetQualityLevel()+" skinWeights="+QualitySettings.skinWeights+" avatar="+a.avatar.name);
        foreach(var r in a.GetComponentsInChildren<SkinnedMeshRenderer>()){
            var m=r.sharedMesh;lines.Add("MESH "+r.name+" vertices="+m.vertexCount+" quality="+r.quality+" root="+(r.rootBone?r.rootBone.name:"null")+" bones="+r.bones.Length+" bindposes="+m.bindposes.Length);
            for(int bi=0;bi<r.bones.Length;bi++){var bone=r.bones[bi];if(!bone)continue;var expected=r.transform.worldToLocalMatrix*bone.localToWorldMatrix;var imported=m.bindposes[bi].inverse;lines.Add("  BIND "+bone.name+" delta="+Vector3.Distance(expected.GetColumn(3),imported.GetColumn(3)).ToString("F5")+" expectedPos="+expected.GetColumn(3)+" bindPos="+imported.GetColumn(3));}
            var counts=new Dictionary<int,float>();foreach(var w in m.boneWeights){int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};for(int i=0;i<4;i++){if(!counts.ContainsKey(ids[i]))counts[ids[i]]=0;counts[ids[i]]+=ws[i];}}
            foreach(var kv in counts.OrderByDescending(k=>k.Value))if(kv.Value>.1f){var b=r.bones[kv.Key];lines.Add("  "+kv.Key+" "+(b?b.name:"MISSING")+" influence="+kv.Value+" local="+(b?b.localPosition.ToString():"")+" scale="+(b?b.lossyScale.ToString():""));}
        }
        foreach(var bone in new[]{HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg,HumanBodyBones.LeftFoot,HumanBodyBones.RightUpperLeg,HumanBodyBones.RightLowerLeg,HumanBodyBones.RightFoot}){var t=a.GetBoneTransform(bone);lines.Add(bone+" => "+t.name+" local="+t.localPosition+" rot="+t.localRotation);}
        File.WriteAllLines(Path.Combine(Folder,"mesh.txt"),lines);
    }

    static bool runtimeIK;static PlayableGraph runtimeGraph;static bool running,oldBackground;static Animator runtimeAnimator;static Camera runtimeCamera;static GameObject runtimeModel;static float start,nextFrame;static int runtimeIndex;static Texture2D runtimeSheet;static List<Pose> runtimePoses;
    static void BeginRuntime(){if(Application.isPlaying)throw new Exception("Start in Edit mode");EditorSceneManager.SaveScene(SceneManager.GetActiveScene());SessionState.SetBool("ZU.LegRuntime",true);EditorApplication.isPaused=false;EditorApplication.isPlaying=true;}
    static void Mode(PlayModeStateChange change){if(change!=PlayModeStateChange.EnteredPlayMode||!SessionState.GetBool("ZU.LegRuntime",false))return;SessionState.SetBool("ZU.LegRuntime",false);oldBackground=Application.runInBackground;Application.runInBackground=true;var p=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var live=p.GetComponent<HumanoidAnimationDriver>().Animator;runtimeModel=UnityEngine.Object.Instantiate(live.gameObject);runtimeModel.name="Temporary leg QA";runtimeModel.transform.SetPositionAndRotation(new Vector3(-1000,50+live.transform.localPosition.y,-1000),Quaternion.identity);foreach(var b in runtimeModel.GetComponentsInChildren<MonoBehaviour>())b.enabled=false;runtimeAnimator=runtimeModel.GetComponent<Animator>();runtimeAnimator.cullingMode=AnimatorCullingMode.AlwaysAnimate;runtimeAnimator.SetBool("Crouching",false);runtimeAnimator.SetFloat("Speed",2.3f);runtimeAnimator.Play("Standing",0,0);runtimeIK=SessionState.GetBool("ZU.LegIK",false);SessionState.SetBool("ZU.LegIK",false);if(runtimeIK){runtimeAnimator.runtimeAnimatorController=null;RuntimeGraph("Walking2");}var cg=new GameObject("Temporary leg QA camera");runtimeCamera=cg.AddComponent<Camera>();runtimeCamera.orthographic=true;runtimeCamera.orthographicSize=1.05f;runtimeCamera.clearFlags=CameraClearFlags.SolidColor;runtimeCamera.backgroundColor=new Color(.27f,.3f,.34f);runtimeCamera.transform.position=new Vector3(-997,50.05f,-997);runtimeCamera.transform.LookAt(new Vector3(-1000,49.92f,-1000));runtimeSheet=new Texture2D(2240,800,TextureFormat.RGB24,false);runtimePoses=new List<Pose>();runtimeIndex=0;start=Time.time;nextFrame=start+1;running=true;}
    static void RuntimeGraph(string clip){runtimeGraph=PlayableGraph.Create("IK cycle QA");var motion=AnimationClipPlayable.Create(runtimeGraph,Clip(clip));motion.SetApplyFootIK(true);var output=AnimationPlayableOutput.Create(runtimeGraph,"Pose",runtimeAnimator);output.SetSourcePlayable(motion);runtimeGraph.Play();}
    static void RuntimeTick(){if(!running||!Application.isPlaying)return;EditorApplication.QueuePlayerLoopUpdate();if(Time.time<nextFrame)return;try{int col=runtimeIndex%8,row=runtimeIndex/8;runtimePoses.Add(Measure(runtimeAnimator,Time.time-start));var tex=Frame(runtimeCamera,280,400);runtimeSheet.SetPixels(col*280,(1-row)*400,280,400,tex.GetPixels());UnityEngine.Object.Destroy(tex);runtimeIndex++;nextFrame=Time.time+(row==0?.175f:.09f);if(runtimeIndex==8){if(runtimeIK){runtimeGraph.Destroy();RuntimeGraph("Running");}else{runtimeAnimator.SetFloat("Speed",5.2f);runtimeAnimator.Play("Standing",0,0);}nextFrame=Time.time+1;}if(runtimeIndex==16){runtimeSheet.Apply();File.WriteAllBytes(Path.Combine(Folder,runtimeIK?"runtime-ik-cycle.png":"runtime-cycle.png"),runtimeSheet.EncodeToPNG());File.WriteAllText(Path.Combine(Folder,runtimeIK?"runtime-ik-poses.json":"runtime-poses.json"),JsonUtility.ToJson(new Cycle{model="PlayerChar live controller",frames=runtimePoses.ToArray()},true));running=false;if(runtimeGraph.IsValid())runtimeGraph.Destroy();Application.runInBackground=oldBackground;EditorApplication.isPlaying=false;}}catch(Exception e){running=false;File.WriteAllText(Path.Combine(Folder,"error.txt"),e.ToString());Application.runInBackground=oldBackground;EditorApplication.isPlaying=false;}}
    static void NaturalCrouch(){
        if(Application.isPlaying)throw new Exception("Apply in Edit mode");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected current UTS");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var a=player.GetComponent<HumanoidAnimationDriver>().Animator;var controller=a.runtimeAnimatorController as AnimatorController;var state=controller.layers[0].stateMachine.states.Single(s=>s.state.name=="Crouching").state;if(!state.iKOnFeet)throw new Exception("Crouch foot retargeting is not enabled");var correction=a.GetComponent<CrouchPoseAlignment>();if(!correction)throw new Exception("Correction was already removed; inspect");UnityEngine.Object.DestroyImmediate(correction);var so=new SerializedObject(player);so.FindProperty("crouchHeight").floatValue=1.6f;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(player);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Folder,"natural-crouch.txt"),"Native Humanoid foot IK; forced body lowering removed; crouch collision envelope 1.60 m accommodates the supplied walk pose.");
    }
    static void FixCrouch(){
        if(Application.isPlaying)throw new Exception("Fix in Edit mode");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected UTS");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var a=player.GetComponent<HumanoidAnimationDriver>().Animator;var controller=a.runtimeAnimatorController as AnimatorController;var state=controller.layers[0].stateMachine.states.Single(s=>s.state.name=="Crouching").state;if(state.iKOnFeet)throw new Exception("Crouching Foot IK already enabled; inspect");
        string backup="Assets/CharacterUpgrade/Backups/Crouch_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");Directory.CreateDirectory(backup);AssetDatabase.Refresh();EditorSceneManager.SaveScene(scene,backup+"/UTS_BeforeCrouchIK.unity",true);AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(controller),backup+"/Player_BeforeCrouchIK.controller");File.Copy("Assets/Scripts/UTS/Characters/CrouchPoseAlignment.cs",backup+"/CrouchPoseAlignment.cs.txt");state.iKOnFeet=true;EditorUtility.SetDirty(state);EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.WriteAllText(Path.Combine(Folder,"crouch-fix.txt"),backup);
    }
    static void Fix(){
        if(Application.isPlaying)throw new Exception("Fix in Edit mode");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected current UTS scene");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var a=player.GetComponent<HumanoidAnimationDriver>().Animator;var controller=a.runtimeAnimatorController as AnimatorController;if(!controller)throw new Exception("Expected editable player controller");var standing=controller.layers[0].stateMachine.states.Single(s=>s.state.name=="Standing").state;if(standing.iKOnFeet)throw new Exception("Foot IK already enabled; inspect rather than applying again");
        string backup="Assets/CharacterUpgrade/Backups/Locomotion_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");Directory.CreateDirectory(backup);AssetDatabase.Refresh();EditorSceneManager.SaveScene(scene,backup+"/UTS_BeforeFootIK.unity",true);AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(controller),backup+"/Player_BeforeFootIK.controller");
        standing.iKOnFeet=true;EditorUtility.SetDirty(standing);EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.WriteAllText(Path.Combine(Folder,"fix.txt"),"Standing.iKOnFeet: false -> true; existing clips, thresholds, avatars, model, map, actor transforms and gameplay retained. Backup: "+backup);
    }
}
